#include <iostream>
#include <cmath>
#include <cstdio>
#include <vector>
#include <algorithm>

using namespace std;

double EPS = 1e-10;

double add(double a, double b) {
    return (fabs(a + b) < EPS * (fabs(a) + fabs(b))) ? 0 : a + b;
}

struct point {
    double x, y;
    point() {}
    point(double x, double y) : x(x), y(y) {}

    point operator + (point p) {
        return point(add(x, p.x), add(y, p.y));
    }

    point operator - (point p) {
        return point(add(x, -p.x), add(y, -p.y));
    }

    point operator * (double d) {
        return point(x * d, y * d);
    }

    point operator / (double d) {
        return point(x / d, y / d);
    }
};

// Modified dist function to return squared distance
double distSquared(point a, point b) {
    return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
}

int main(void) {
    int n, x, y, v;
    vector<point> P;
    vector<double> V;

    while (cin >> n, n) {
        P.clear();
        V.clear();

        for (int i = 0; i < n; i++) {
            cin >> x >> y >> v;
            P.emplace_back(x, y);
            V.push_back(v);
        }

        double r = 0.999;
        point now(0, 0);

        for (double d = 10; d > EPS; d *= r) {
            int mx = 0;
            double mxd = 0;

            for (int j = 0; j < P.size(); j++) {
                double distance = distSquared(now, P[j]) / (V[j] * V[j]); // Using squared distance
                if (distance > mxd) {
                    mx = j;
                    mxd = distance;
                }
            }

            now = now + ((P[mx] - now) / sqrt(distSquared(P[mx], now)) * d);
        }

        double ans = 0;
        for (int i = 0; i < P.size(); i++) {
            ans = max(ans, sqrt(distSquared(now, P[i])) / V[i]);
        }

        printf("%.8f\n", ans);
    }

    return 0;
}

